// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0));
        amount = bound(amount, 1, type(uint128).max);
        vm.prank(c.owner());
        c.mintToken(target, amount);
        // Invariant: totalSupply equals the sum of all credited balances; a mint must
        // increase the target's balance by the same amount it increases totalSupply.
        assertTrue(c.balanceOf(target) == c.totalSupply());
    }
}
